#!/usr/bin/env node
// Для сборки tg-channel-manager_1: favicon и логотип с надписью «Менеджер каналов» на формах входа и регистрации.
// Запуск из корня проекта:  node apply-branding-build1.mjs
// Изменяемые файлы копируются в <файл>.bak. Повторный запуск безопасен.
import fs from 'node:fs';
import path from 'node:path';

const DATA = {
 "edits": [
  {
   "file": "assets/main.css",
   "hunks": [
    {
     "old": ".actions { display: flex; gap: var(--s-2); flex-wrap: wrap; margin-top: var(--s-3); }\n.auth-card { max-width: 380px; margin: var(--s-8) auto; }\n.auth-card h1 { margin-bottom: var(--s-3); }\n\n/* вспомогательные отступы (идут после .error и т.п., чтобы переопределять их) */\n.mt-1 { margin-top: var(--s-1); }\n",
     "new": ".actions { display: flex; gap: var(--s-2); flex-wrap: wrap; margin-top: var(--s-3); }\n.auth-card { max-width: 380px; margin: var(--s-8) auto; }\n.auth-card h1 { margin-bottom: var(--s-3); }\n.auth-brand { display: flex; align-items: center; justify-content: center; gap: var(--s-3); margin-bottom: var(--s-5); font-size: 20px; font-weight: 600; }\n.auth-logo { display: block; height: 40px; width: auto; }\n\n/* вспомогательные отступы (идут после .error и т.п., чтобы переопределять их) */\n.mt-1 { margin-top: var(--s-1); }\n"
    }
   ]
  },
  {
   "file": "nuxt.config.ts",
   "hunks": [
    {
     "old": "  compatibilityDate: '2025-01-01',\n  ssr: false, // SPA: Express-API живёт в том же процессе (см. server/middleware/api.ts)\n  css: ['~/assets/main.css'],\n  app: { head: { title: 'Менеджер каналов', htmlAttrs: { lang: 'ru' } } },\n})\n",
     "new": "  compatibilityDate: '2025-01-01',\n  ssr: false, // SPA: Express-API живёт в том же процессе (см. server/middleware/api.ts)\n  css: ['~/assets/main.css'],\n  app: {\n    head: {\n      title: 'Менеджер каналов',\n      htmlAttrs: { lang: 'ru' },\n      link: [{ rel: 'icon', type: 'image/x-icon', href: '/favicon.ico' }],\n    },\n  },\n})\n"
    }
   ]
  },
  {
   "file": "pages/login.vue",
   "hunks": [
    {
     "old": "\n<template>\n  <form class=\"card auth-card\" @submit.prevent=\"submit\">\n    <h1>{{ needsSetup ? 'Создание администратора' : 'Вход' }}</h1>\n    <p v-if=\"needsSetup\" class=\"muted\">Пользователей пока нет. Эта учётная запись станет администратором.</p>\n\n",
     "new": "\n<template>\n  <form class=\"card auth-card\" @submit.prevent=\"submit\">\n    <AuthBrand />\n    <h1>{{ needsSetup ? 'Создание администратора' : 'Вход' }}</h1>\n    <p v-if=\"needsSetup\" class=\"muted\">Пользователей пока нет. Эта учётная запись станет администратором.</p>\n\n"
    }
   ]
  },
  {
   "file": "pages/register.vue",
   "hunks": [
    {
     "old": "\n<template>\n  <form v-if=\"registration.open\" class=\"card auth-card\" @submit.prevent=\"submit\">\n    <h1>Регистрация</h1>\n    <p class=\"muted\">\n      Вы получите собственное изолированное пространство: свои каналы, редакторов и источники парсера.\n",
     "new": "\n<template>\n  <form v-if=\"registration.open\" class=\"card auth-card\" @submit.prevent=\"submit\">\n    <AuthBrand />\n    <h1>Регистрация</h1>\n    <p class=\"muted\">\n      Вы получите собственное изолированное пространство: свои каналы, редакторов и источники парсера.\n"
    },
    {
     "old": "  </form>\n\n  <div v-else class=\"card auth-card\">\n    <h1>Регистрация</h1>\n    <p class=\"muted\">Самостоятельная регистрация отключена. Попросите администратора создать для вас аккаунт.</p>\n    <p class=\"muted\"><NuxtLink to=\"/login\">Войти</NuxtLink></p>\n",
     "new": "  </form>\n\n  <div v-else class=\"card auth-card\">\n    <AuthBrand />\n    <h1>Регистрация</h1>\n    <p class=\"muted\">Самостоятельная регистрация отключена. Попросите администратора создать для вас аккаунт.</p>\n    <p class=\"muted\"><NuxtLink to=\"/login\">Войти</NuxtLink></p>\n"
    }
   ]
  }
 ],
 "files": {
  "components/AuthBrand.vue": "<template>\n  <div class=\"auth-brand\">\n    <img src=\"/logo.png\" alt=\"\" class=\"auth-logo\" />\n    <span>Менеджер каналов</span>\n  </div>\n</template>\n"
 },
 "bin": {
  "public/favicon.ico": "",
  "public/logo.png": ""
 }
};

const root = process.cwd();
for (const marker of ['nuxt.config.ts', 'pages/register.vue', 'server/express/secrets.js', 'server/express/bot.js']) {
  if (!fs.existsSync(path.join(root, marker))) {
    console.error(`Не найден ${marker}. Скрипт рассчитан на сборку tg-channel-manager_1 — запустите его из её корня.`);
    process.exit(1);
  }
}
const backup = (file) => { const bak = file + '.bak'; if (!fs.existsSync(bak)) fs.copyFileSync(file, bak); };
const count = (s, sub) => s.split(sub).length - 1;

// 1) проверяем все правки заранее: либо применяем всё, либо ничего
const plan = [];
let failed = false;
for (const { file, hunks } of DATA.edits) {
  const full = path.join(root, file);
  if (!fs.existsSync(full)) { console.error(`✗ нет файла ${file}`); failed = true; continue; }
  let text = fs.readFileSync(full, 'utf8');
  let changed = false;
  hunks.forEach((h, i) => {
    if (count(text, h.new) >= 1) { /* уже применено */ }
    else if (count(text, h.old) === 1) { text = text.replace(h.old, () => h.new); changed = true; }
    else { console.error(`✗ ${file}: фрагмент #${i + 1} не найден (файл изменён после выгрузки сборки?)`); failed = true; }
  });
  plan.push({ full, file, text, changed });
}
if (failed) { console.error('\nНичего не изменено.'); process.exit(1); }

// 2) записываем
for (const p of plan) {
  if (!p.changed) { console.log(`= ${p.file} (уже применено)`); continue; }
  backup(p.full);
  fs.writeFileSync(p.full, p.text);
  console.log(`✓ ${p.file}`);
}
const put = (file, buf) => {
  const full = path.join(root, file);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  if (fs.existsSync(full)) {
    if (fs.readFileSync(full).equals(buf)) return console.log(`= ${file} (уже применено)`);
    backup(full);
  }
  fs.writeFileSync(full, buf);
  console.log(`✓ ${file}`);
};
for (const [file, content] of Object.entries(DATA.files)) put(file, Buffer.from(content, 'utf8'));
for (const [file, b64] of Object.entries(DATA.bin)) put(file, Buffer.from(b64, 'base64'));

console.log('\nГотово. Перезапустите приложение (npm run dev / npm run build + перезапуск).');
console.log('Если favicon не обновился — обновите страницу с очисткой кэша (Ctrl+F5).');
